/* League aggregates use summed team totals, never averages of team percentages. */
const leagueOverviewUI={season:'current',competition:'regular'};
function leagueOverviewChange(key,value){if(key==='season'&&(value==='current'||teamStatsSeasons().includes(Number(value))))leagueOverviewUI.season=value;if(key==='competition'&&['regular','playoffs','preseason'].includes(value))leagueOverviewUI.competition=value;render()}
function leagueAggregate(rows){
 const active=rows.filter(r=>r.gp>0),teamGames=active.reduce((n,r)=>n+r.gp,0),data={teams:active.length,teamGames,games:teamGames/2};
 for(const key of ['pts','fgm','fga','tpm','tpa','ftm','fta','orb','drb','reb','ast','tov','stl','blk','pf','poss','defPoss','mp'])data[key]=active.length&&active.every(r=>Number.isFinite(r[key]))?active.reduce((n,r)=>n+r[key],0):null;
 const ratio=(n,d)=>Number.isFinite(n)&&Number.isFinite(d)&&d>0?n/d:null;
 data.fgp=ratio(data.fgm,data.fga);data.tpp=ratio(data.tpm,data.tpa);data.ftp=ratio(data.ftm,data.fta);
 data.efg=Number.isFinite(data.fgm)&&Number.isFinite(data.tpm)?ratio(data.fgm+.5*data.tpm,data.fga):null;
 data.ts=Number.isFinite(data.fga)&&Number.isFinite(data.fta)?ratio(data.pts,2*(data.fga+.44*data.fta)):null;
 data.ortg=ratio(data.pts,data.poss);if(data.ortg!==null)data.ortg*=100;
 data.pace=Number.isFinite(data.poss)&&Number.isFinite(data.defPoss)?ratio((data.poss+data.defPoss)*24,data.mp):null;
 data.astTo=ratio(data.ast,data.tov);data.astPct=ratio(data.ast,data.fgm);data.tovPct=ratio(data.tov,data.poss);data.ftaRate=ratio(data.fta,data.fga);data.threeRate=ratio(data.tpa,data.fga);data.orebPct=Number.isFinite(data.orb)&&Number.isFinite(data.drb)?ratio(data.orb,data.orb+data.drb):null;
 return data;
}
function leagueOverviewView(){
 const ui=leagueOverviewUI,years=teamStatsSeasons();if(ui.season!=='current'&&!years.includes(Number(ui.season)))ui.season='current';const year=ui.season==='current'?state.year:Number(ui.season),data=leagueAggregate(teamStatRows('all',ui.competition,ui.season));
 const number=(value,digits=1)=>Number.isFinite(value)?value.toLocaleString('en-US',{minimumFractionDigits:digits,maximumFractionDigits:digits}):'—',pct=value=>value===null?'—':number(value*100)+'%',per=value=>Number.isFinite(value)&&data.teamGames?value/data.teamGames:null;
 const cards=[['RECORDED GAMES',number(data.games,0),'Each matchup counted once'],['SCORING',number(per(data.pts)),'Points per team per game'],['FIELD GOALS',pct(data.fgp),'Combined league shooting'],['PACE',number(data.pace),'Possessions per team per 48 minutes']];
 const counts=[['pts','Points'],['fgm','Field goals made'],['fga','Field goals attempted'],['tpm','Three-pointers made'],['tpa','Three-pointers attempted'],['ftm','Free throws made'],['fta','Free throws attempted'],['orb','Offensive rebounds'],['drb','Defensive rebounds'],['reb','Total rebounds'],['ast','Assists'],['tov','Turnovers'],['stl','Steals'],['blk','Blocks'],['pf','Personal fouls']];
 const rates=[['fgp','FG%',true],['tpp','3P%',true],['ftp','FT%',true],['efg','eFG%',true],['ts','TS%',true],['ortg','Points per 100 possessions',false],['pace','Pace (per 48 minutes)',false],['astPct','AST% (assists / field goals made)',true],['astTo','Assist / turnover ratio',false],['tovPct','TOV% (turnovers / possessions)',true],['orebPct','Offensive rebound share',true],['ftaRate','FTA rate (FTA / FGA)',false],['threeRate','Three-point attempt rate',true]];
 return `<div class="league-overview"><section class="panel"><div class="panelhead"><div><h2>League-wide statistics</h2><small>${escapeHTML(state.leagueName||'Hoops Dynasty')} · ${data.teams} teams with recorded games</small></div></div><div class="note tm-grid"><label>Season<select onchange="leagueOverviewChange('season',this.value)">${years.map(y=>`<option value="${y===state.year?'current':y}" ${y===year?'selected':''}>${y}–${y+1}</option>`).join('')}</select></label><label>Season type<select onchange="leagueOverviewChange('competition',this.value)">${[['preseason','Preseason'],['regular','Regular Season'],['playoffs','Playoffs']].map(([key,label])=>`<option value="${key}" ${ui.competition===key?'selected':''}>${label}</option>`).join('')}</select></label></div></section><div class="league-summary">${cards.map(([label,value,help])=>`<section class="panel"><small>${label}</small><strong>${value}</strong><span>${help}</span></section>`).join('')}</div>${!data.teamGames?`<p class="note">${ui.competition==='preseason'?'Preseason games coming soon.':'No recorded games for this season and competition yet.'}</p>`:''}<div class="league-stat-panels"><section class="panel"><div class="panelhead"><h2>Traditional statistics</h2></div><div class="scroll"><table><thead><tr><th>Statistic</th><th>League total</th><th>Per team / game</th></tr></thead><tbody>${counts.map(([key,label])=>`<tr><th scope="row">${label}</th><td>${number(data[key],0)}</td><td>${number(per(data[key]))}</td></tr>`).join('')}</tbody></table></div></section><section class="panel"><div class="panelhead"><h2>Shooting & efficiency</h2></div><div class="scroll"><table><thead><tr><th>Metric</th><th>League value</th></tr></thead><tbody>${rates.map(([key,label,percent])=>`<tr><th scope="row">${label}</th><td>${percent?pct(data[key]):number(data[key],key==='astTo'||key==='ftaRate'?2:1)}</td></tr>`).join('')}</tbody></table></div></section></div><p class="note">Totals include every team. Per-game averages are per team appearance (${number(data.teamGames,0)} across ${number(data.games,0)} games). Shooting percentages and efficiency use summed totals, so teams are weighted by attempts and possessions. — indicates missing tracking data or no qualifying attempts. Archived seasons use saved statistical records.</p></div>`;
}
